def word_count(text, counts=None):
    if counts is None:
        counts = {}

    # Split by any whitespace instead of just " " to handle tabs, newlines, multiple spaces, etc.
    for word in text.split():
        # Strip leading/trailing punctuation and convert to lowercase
        word = word.strip(".,!?;:").lower()

        # Skip empty results after stripping
        if word:
            counts[word] = counts.get(word, 0) + 1

    return counts
